// AI pre-translation of Chat AI - frontend keys that are still empty in a target language (reusable).
// Run 22 Oct 2026: 112 new landing:: keys (landing page), empty in de, es, fr, it, nl, pt.
// Run 26 Oct 2026: tag 2610, 4 new image-style titles (landing::imageStyles::items::*::title), 24 translations written (exec 908431).
// Run 28 Oct 2026: AICHAT-1538 Lighting & Color Correction, 121 keys.
// Keep MODE 'check'; switch to 'write' deliberately for a run, then back.
const MODE = 'check';
const LANGS = ['de', 'es', 'fr', 'it', 'nl', 'pt'];
const KEY_PREFIX = '';   // optional: only keys whose name starts with this (e.g. 'landing::'); '' = every key with an empty target
const CHUNK = 40;
const BATCH = "Batch: AICHAT-1538 Lighting & Color Correction funnel (landing, settings screen with presets and sliders, chat result).";
const NOTES = "FEATURE CONTEXT (AICHAT-1538, Lighting & Color Correction funnel): every item has a description (context) - read it. Keys under lightingColor::editor::prompt::* are NOT UI: the app sends them to the image AI model in the user's language. Translate them as clear, precise instructions to an AI image editor, same meaning, no marketing tone. prompt::adjust::*::up/down are lowercase instruction fragments with no final period; the app inserts one into strength patterns 'slightly [%1$s:action]' / 'strongly [%1$s:action]' / '[%1$s:action]' and joins several with the language's list format, then into 'Apply these adjustments: [%1$s:list].' - make fragments and patterns combine grammatically. prompt::system: keep the tool name in quotes; keep every rule. Brand 'Chatbot Online' unchanged. File format lists (JPG, JPEG, PNG, WEBP) unchanged. Keep <strong> tags. Numbers like 600K+ and 1.2M+ follow the target language's number conventions. Preset names (Auto, Bright, Warm, Cool, Vivid, Food, Interior, Night) are short tile labels; slider names (Brightness, Contrast, Highlights, Shadows, Warmth, Tint, Saturation) use the standard photo-editing terms of the target language (as in Lightroom or phone photo editors).";
return [{ json: { mode: MODE, langs: LANGS, prefix: KEY_PREFIX, chunk: CHUNK, batch: BATCH, notes: NOTES } }];

const b = $input.first().json.body || $input.first().json;
if (!Array.isArray(b.projects)) { throw new Error('projects fetch failed'); }
const re = /(chat ?ai|chatbot)/i;
return b.projects.filter(function (p) { return re.test(p.name) && !/html|legal/i.test(p.name); })
  .map(function (p) { return { json: { pid: p.project_id, name: p.name, url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor' } }; });

// Builds one OpenAI request per (language, chunk of keys). Read-only. Targets: Chat AI - frontend keys with an empty target.
const cfg = $('Config').first().json;
const FE = '691331356a3b9a68428ab3.43540470';
const LN = { de: 'German', es: 'Spanish (Spain)', fr: 'French', it: 'Italian', nl: 'Dutch', pt: 'Brazilian Portuguese (pt-BR)' };
const ISO_BY_ID = { 666: 'de', 640: 'en', 1056: 'es', 673: 'fr', 734: 'it', 737: 'nl', 708: 'pt' };
function txt(v) { if (v === null || v === undefined) { return ''; } if (typeof v === 'object') { return JSON.stringify(v); } return String(v); }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || ''); }
const corpus = []; const targets = [];
for (const it of $('Fetch corpus').all()) {
  const b = it.json.body || {}; if (!Array.isArray(b.keys)) { continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    const tr = {}; let en = '';
    for (const t of (k.translations || [])) { const s = txt(t.translation); if (t.language_iso === 'en') { en = s; } else if (s.trim()) { tr[t.language_iso] = s; } }
    if (!en.trim()) { continue; }
    const row = { id: k.key_id, name: kn(k), pid: b.project_id, en: en, t: tr, d: String(k.description || '') };
    const missing = cfg.langs.filter(function (l) { return !tr[l]; });
    if (b.project_id === FE && missing.length && (!cfg.prefix || row.name.indexOf(cfg.prefix) === 0)) { targets.push(row); }
    if (Object.keys(tr).length) { corpus.push(row); }
  }
}
if (!targets.length) { throw new Error('No target keys with empty targets found'); }
targets.sort(function (a, b) { return a.name.localeCompare(b.name); });
function norm(s) { return String(s).replace(/<[^>]+>/g, ' ').replace(/\[%[^\]]*\]/g, ' X ').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase(); }
function toks(s) { return new Set((norm(s).match(/[\p{L}\p{N}']{2,}/gu) || [])); }
for (const c of corpus) { c.n = norm(c.en); c.w = toks(c.en); }
const byN = {}; for (const c of corpus) { (byN[c.n] = byN[c.n] || []).push(c); }
for (const t of targets) {
  t.n = norm(t.en); const W = toks(t.en); const ex = (byN[t.n] || []).filter(function (c) { return c.id !== t.id; });
  const fz = [];
  if (W.size >= 2) {
    for (const c of corpus) {
      if (c.n === t.n || !c.w.size || c.id === t.id) { continue; }
      const r = c.w.size / W.size; if (r < 0.5 || r > 2) { continue; }
      let i = 0; W.forEach(function (x) { if (c.w.has(x)) { i++; } });
      const sc = 2 * i / (W.size + c.w.size);
      if (sc >= 0.6) { fz.push({ c: c, sc: sc }); }
    }
  }
  fz.sort(function (a, b) { return b.sc - a.sc || (a.c.pid === FE ? -1 : 1); });
  t.ex = ex.sort(function (a, b) { return (a.pid === FE ? -1 : 1); }).slice(0, 3);
  t.fz = fz.slice(0, 3);
}
const RULES = {}, JUDGE = {};
for (const it of $('Style rules').all()) { const r = it.json || {}; if (!r.iso || r.iso === '*') { continue; } let l = []; try { l = JSON.parse(r.rules_json || '[]'); } catch (e) { } RULES[r.iso] = l.filter(function (x) { return !x.project || x.project !== 'personality'; }).map(function (x) { return (x.desc || x.id) + (x.suggest ? ' (use: ' + x.suggest + ')' : ''); }); JUDGE[r.iso] = r.judgement || ''; }
const FB = {};
for (const it of $('Feedback').all()) { const r = it.json || {}; if (!r.iso || !r.decision) { continue; } (FB[r.iso] = FB[r.iso] || []).push({ d: r.decision, rule: String(r.rule || '').slice(0, 80), en: String(r.en || '').slice(0, 120), t: String(r.translation || '').slice(0, 120), why: String(r.reason || r.issue || '').slice(0, 160) }); }
const GUIDE = {};
const gp = $('Guide plan').all(); const ge = $('Export guides').all();
for (let i = 0; i < gp.length; i++) { const iso = gp[i].json.iso; const g = ge[i] ? ge[i].json : {}; const s = typeof g.data === 'string' ? g.data : ''; if (s && iso !== '__none__') { GUIDE[iso] = s.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 24000); } }
let terms = [];
for (const it of $('Glossary').all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []); }
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) { const raw = t.tags || []; const arr = Array.isArray(raw) ? raw : String(raw).split(','); return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; }); }
const allTags = {}; for (const t of terms) { for (const g of tagList(t)) { allTags[g] = (allTags[g] || 0) + 1; } }
const inScope = terms.filter(function (t) { const tg = tagList(t); return !tg.length || tg.indexOf('shared') !== -1 || tg.some(function (g) { return /chat/.test(g); }); });
function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function glossFor(iso, ens) {
  const out = []; const blob = ens.join(' \n ');
  for (const t of inScope) {
    const src = String(t.term || '').trim(); if (!src) { continue; }
    const rx = new RegExp('(?<![\\p{L}\\p{N}])' + esc(src) + '(?![\\p{L}\\p{N}])', 'u' + (yes(t.caseSensitive) ? '' : 'i'));
    if (!rx.test(blob)) { continue; }
    let tgt = '', note = '';
    for (const tr of (t.translations || [])) { const i2 = ISO_BY_ID[tr.langId || tr.lang_id] || (String(tr.langIso || tr.lang_iso || '') === 'pt_BR' ? 'pt' : String(tr.langIso || tr.lang_iso || '')); if (i2 === iso) { tgt = String(tr.translation || '').trim(); note = String(tr.description || '').trim(); } }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    out.push({ term: src, target: translatable ? tgt : '(do not translate: keep as is)', forbidden: yes(t.forbidden) || undefined, note: (note || String(t.description || '')).slice(0, 160) || undefined });
  }
  return out;
}
const NL = String.fromCharCode(10);
const jobs = [];
for (const iso of cfg.langs) {
  const todo = targets.filter(function (t) { return !t.t[iso]; });
  if (!todo.length) { continue; }
  const fb = (FB[iso] || []).slice(-15);
  for (let c = 0; c < todo.length; c += cfg.chunk) {
    const part = todo.slice(c, c + cfg.chunk);
    const items = part.map(function (t) {
      const tm = [];
      for (const e of t.ex) { if (e.t[iso]) { tm.push({ match: '100% (exact)', en: e.en, translation: e.t[iso] }); } }
      for (const f of t.fz) { if (f.c.t[iso]) { tm.push({ match: 'fuzzy ' + Math.round(f.sc * 100) + '%', en: f.c.en, translation: f.c.t[iso] }); } }
      return { id: String(t.id), key: t.name, en: t.en, context: t.d.slice(0, 900) || undefined, tm: tm.length ? tm.slice(0, 4) : undefined };
    });
    const SYS = [
      'You are a senior native ' + LN[iso] + ' localizer translating UI and marketing strings of Chatbot Online (internally "Chat AI"), a web app that gives one subscription access to many AI chat models (GPT-5, Claude, Gemini, Grok and more) and image models, plus AI photo tools (image enhancer, background remover, image generator). ' + cfg.batch,
      'Translate every item from English into ' + LN[iso] + '. Write natural, idiomatic, concise product copy a native speaker would expect in a polished web app, not a literal rendering. The key name tells you where the text sits on the page (title, description, cta, label...).',
      'PRIORITIES, in order: (1) the ' + LN[iso] + ' STYLE GUIDE below (register/formality, tone, typography, number/date/punctuation conventions); (2) the GLOSSARY (use the approved target terms; never use forbidden terms; keep brand names unchanged); (3) TRANSLATION MEMORY: items may carry 100% (exact) matches and fuzzy matches from our approved Chat AI translations. Reuse a 100% match verbatim unless it breaks the glossary or style guide or does not fit the context. Reuse terminology and phrasing from fuzzy matches so the landing page reads like the existing app.',
      cfg.notes,
      'MECHANICS (strict): keep every placeholder exactly as in the source (e.g. [%1$s:max], {count}); keep any HTML tags exactly (same count). Do not add or remove leading/trailing spaces. Identical English strings in this batch must get identical translations.',
      'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id (not the key name), with an entry for EVERY id.',
      '',
      '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
      GUIDE[iso] ? GUIDE[iso] : '(full guide unavailable; use the rules below)',
      '',
      '=== Style rules distilled by the i18n team ===',
      (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
      JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
      fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
    ].join(NL);
    const user = { language: LN[iso], glossary: glossFor(iso, part.map(function (t) { return t.en; })), items: items };
    jobs.push({ json: { iso: iso, chunk: c / cfg.chunk, ids: part.map(function (t) { return t.id; }), guide: !!GUIDE[iso], gloss_n: user.glossary.length, gloss_tags: allTags, body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 16000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(user) }] }) } });
  }
}
return jobs;

// Parses OpenAI answers, validates mechanics, unifies identical English. Read-only.
const jobs = $('Build jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
function bag(s, rx) { const m = {}; for (const x of (String(s).match(rx) || [])) { m[x] = (m[x] || 0) + 1; } return JSON.stringify(Object.keys(m).sort().map(function (k) { return k + ':' + m[k]; })); }
const PH = /\[%[^\]]*\]|\{[^{}]*\}/g, TAG = /<\/?[A-Za-z]+[^>]*>/g;
function check(en, t) {
  if (!t || !String(t).trim()) { return 'empty'; }
  if (bag(en, PH) !== bag(t, PH)) { return 'placeholder mismatch'; }
  if (bag(en, TAG) !== bag(t, TAG)) { return 'tag mismatch'; }
  const letters = /\p{L}/u.test(String(en).replace(PH, ''));
  // Untranslated = identical AND the source has an ordinary lowercase word (names-only strings such as model lists may stay identical).
  if (letters && String(t).trim() === String(en).trim() && /(^|[^\p{L}])\p{Ll}{4,}/u.test(String(en).replace(PH, ''))) { return 'untranslated'; }
  if (t !== t.trim() && en === en.trim()) { return 'extra whitespace'; }
  return '';
}
const per = {}; const bad = []; const callErr = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i]; const r = res[i] || {};
  const items = JSON.parse(JSON.parse(j.body).messages[1].content).items;
  let parsed = null;
  try { parsed = JSON.parse(String(r.choices[0].message.content).replace(/^```json|```$/g, '').trim()).t; } catch (e) { callErr.push({ iso: j.iso, chunk: j.chunk, err: r.error ? JSON.stringify(r.error).slice(0, 200) : String(e.message || e) }); continue; }
  per[j.iso] = per[j.iso] || {};
  for (const it of items) {
    const t = parsed ? (parsed[it.id] !== undefined ? parsed[it.id] : parsed[it.key]) : undefined;
    if (typeof t !== 'string') { bad.push({ iso: j.iso, key: it.key, why: 'missing in answer' }); continue; }
    const why = check(it.en, t);
    if (why) { bad.push({ iso: j.iso, key: it.key, why: why, en: it.en.slice(0, 200), t: String(t).slice(0, 300) }); continue; }
    per[j.iso][it.id] = { key: it.key, en: it.en, t: t, tm: it.tm ? it.tm[0].match : '' };
  }
}
let unified = 0;
for (const iso in per) {
  const groups = {};
  for (const id in per[iso]) { const e = per[iso][id].en.trim(); (groups[e] = groups[e] || []).push(id); }
  for (const e in groups) {
    const ids = groups[e]; if (ids.length < 2) { continue; }
    const cnt = {}; for (const id of ids) { const t = per[iso][id].t; cnt[t] = (cnt[t] || 0) + 1; }
    const best = Object.keys(cnt).sort(function (a, b) { return cnt[b] - cnt[a]; })[0];
    for (const id of ids) { if (per[iso][id].t !== best) { per[iso][id].t = best; unified++; } }
  }
}
const ids = []; for (const j of jobs) { for (const x of j.ids) { if (ids.indexOf(x) === -1) { ids.push(x); } } }
const stats = {}; for (const iso in per) { const v = Object.values(per[iso]); stats[iso] = { ok: v.length, tm_exact_reused: v.filter(function (x) { return x.tm.indexOf('100%') === 0; }).length }; }
return [{ json: { per: per, bad: bad, call_errors: callErr, unified: unified, stats: stats, ids: ids.join(','), guides: jobs.reduce(function (a, j) { a[j.iso] = j.guide; return a; }, {}), gloss_tags: jobs.length ? jobs[0].gloss_tags : {} } }];

// Guard: writes only into translations that are still empty right now, only if EN is unchanged.
// Status: unverified + the project's AI_TO_REVIEW custom status (looked up live; skipped if the project has none).
const p = $('Parse and validate').first().json; const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const sb = $('Statuses').first().json.body || {};
const sts = sb.custom_translation_statuses || [];
const st = sts.filter(function (s) { return /ai.?to.?review/i.test(String(s.title || '')); })[0];
const live = {};
for (const k of b.keys) { const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); } live[k.key_id] = { m: m, arch: k.is_archived }; }
const out = []; const summary = { status: st ? (st.title + ' ' + st.status_id) : 'none found: unverified only', project_statuses: sts.map(function (s) { return s.title + ' ' + s.status_id; }) };
for (const iso in p.per) {
  const keys = []; let skipped = 0, enChanged = 0;
  for (const id in p.per[iso]) {
    const L = live[id]; if (!L || L.arch) { skipped++; continue; }
    if (String(L.m.en || '') !== p.per[iso][id].en) { enChanged++; continue; }
    if (String(L.m[iso] || '').trim()) { skipped++; continue; }
    const tr = { language_iso: iso, translation: p.per[iso][id].t, is_unverified: true };
    if (st) { tr.custom_translation_status_ids = [st.status_id]; }
    keys.push({ key_id: Number(id), translations: [tr] });
  }
  summary[iso] = { to_write: keys.length, skipped_now_filled: skipped, en_changed: enChanged };
  if (keys.length) { out.push({ json: { iso: iso, n: keys.length, body: JSON.stringify({ keys: keys }) } }); }
}
return [{ json: { mode: cfg.mode, summary: summary, stats: p.stats, invalid: p.bad, call_errors: p.call_errors, unified: p.unified, guides: p.guides, writes: out.map(function (o) { return o.json; }) } }];

// Write gate: nothing is written in MODE 'check'.
const d = $input.first().json;
if (d.mode !== 'write') { return []; }
return d.writes.map(function (w) { return { json: w }; });
